def trajectory_SgConst(Sg=0.1, delta_logt_dex=-0.01):
    logtimerev = np.arange(5.0, -6.0, delta_logt_dex)
    logrho = np.linspace(0, 8.5, len(logtimerev))
    logT = old_div(1.0, 3.0) * (logrho + 21.9161 + np.log10(Sg))
    pl.close(3)
    pl.figure(3)
    pl.plot(logrho, logT, label='$S/\\mathrm{N_Ak}=' + str(Sg) + '$')
    pl.legend(loc=2)
    pl.xlabel('$\\log \\rho$')
    pl.ylabel('$\\log T$')
    pl.close(5)
    pl.figure(5)
    pl.plot(logtimerev, logrho)
    pl.xlabel('$\\log (t_\\mathrm{final}-t)$')
    pl.ylabel('$\\log \\rho$')
    pl.xlim(8, -6)
    pl.close(6)
    pl.figure(6)
    pl.plot(logtimerev)
    pl.ylabel('$\\log (t_\\mathrm{final}-t)$')
    pl.xlabel('cycle')
    T9 = old_div(10 ** logT, 1000000000.0)
    data = [logtimerev, T9, logrho]
    att.writeTraj(filename='trajectory.input', data=data, ageunit=2, tunit=
        1, rhounit=1, idNum=1)